
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_dlb97_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_dlb97", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.499416236594374e+00, -4.421460877685155e+00, -4.312473677583775e+00, -4.161996194055036e+00, -3.957935839855906e+00, -3.688246358633863e+00, -3.344596477335292e+00, -2.928107271377334e+00, -2.452822980906777e+00, -1.925940496833555e+00, -1.275213588607387e+00, -7.027654786879673e-01, -5.921995517898374e-01, -5.089015787294926e-01, -3.811136600966636e-01, -2.537965713338501e-01, -1.584460268377706e-01, -6.723555453550964e-02, -1.534032806802710e-02, -1.710865569492125e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


